/** Parse the input into { names (sorted), cost: Map<string,bigint>, deps: Map<string,string[]> (sorted) }. */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const depLines = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new GraphError(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new GraphError(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new GraphError(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new GraphError(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new GraphError(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new GraphError(`error: line ${n}: unknown directive ${w[0]}`)
    }
