  for (const k of cost.keys()) deps.set(k, new Set())
  for (const w of depLines) {
    for (const name of w) if (!cost.has(name)) throw new GraphError(`error: unknown task ${name}`)
    for (const d of w.slice(1)) deps.get(w[0]).add(d)
  }
  const sorted = new Map()
  for (const [k, s] of deps) sorted.set(k, [...s].sort(cmp))
  return { names: [...cost.keys()].sort(cmp), cost, deps: sorted }
}
"}

