  const visit = (n) => {
    state.set(n, 1)
    stack.push(n)
    for (const d of g.deps.get(n)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const r = visit(d)
        if (r) return r
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of g.names) {
    if (!state.get(n)) {
      const r = visit(n)
      if (r) return r
    }
  }
  return null
}

/** Topological order (dependencies first), names ascending among ties of DFS. */
function order(g) {
  const seen = new Set()
  const out = []
  const visit = (n) => {
    seen.add(n)
    for (const d of g.deps.get(n)) if (!seen.has(d)) visit(d)
    out.push(n)
  }
  for (const n of g.names) if (!seen.has(n)) visit(n)
  return out
}

